import glob, json

files = glob.glob('/home/agent/.gemini/tmp/workspace/tool-outputs/session-c8d0cb03-0fd3-4fd5-811b-6f7b3ec97ecd/mcp_mcp429207a6_list_issues_*.txt')

all_issues = {}
for file in files:
    with open(file) as f:
        data = json.load(f)
        for issue in data.get('issues', []):
            all_issues[issue['identifier']] = issue

clusters = {'South': [], 'North': [], 'East': [], 'West': [], 'Other PM': []}

for id_str in sorted(all_issues.keys(), key=lambda x: int(x.split('-')[1])):
    issue = all_issues[id_str]
    title = issue['title']
    desc = issue['description']
    text = (title + ' ' + desc).lower()

    # check if related to PM push / clusters / trades
    if any(k in text for k in ['cluster', 'hvac', 'plumbing', 'electrical', 'spot-check', 'spot check', 'preventive maintenance']):
        assigned = False
        for c in ['south', 'north', 'east', 'west']:
            if c in text:
                clusters[c.capitalize()].append(issue)
                assigned = True
        if not assigned:
            clusters['Other PM'].append(issue)

for c, issue_list in clusters.items():
    print(f'=== {c.upper()} CLUSTER ISSUES ({len(issue_list)}) ===')
    for issue in issue_list:
        assignee = issue['assignee']['name'] if issue.get('assignee') else 'Unassigned'
        proj = issue.get('project', {}).get('id') if issue.get('project') else None
        print(f\"  {issue['identifier']} | {issue['state']['name']:12} | {assignee:18} | {issue['title']}\")
